SELECT COALESCE(act_no, id::text) AS act_no, COALESCE(batch_id,'') AS batch_id, COALESCE(azs_code,'') AS azs_code, COALESCE(tank_code,'') AS tank_code, COALESCE(product_code,'') AS product_code, COALESCE(sample_point,'') AS sample_point, COALESCE(operator_name,'') AS operator_name, status, volume_ml, COALESCE(seal_no,'') AS seal_no, COALESCE(note,'') AS note, sampled_at::text AS sampled_at FROM oc_lab_sample ORDER BY sampled_at DESC
